import os
N=['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten']
DISLO=['COTHIgnoreAmp','COTHTiers','SummonByDeath','PotiEff','stats','DeathRaid','ItemDura','HealingDeath','DamageDeath','FoodDeath','DeathHighVerions','ParasiteNoPotion','HealthDraining','FoodDraining','NextPhaseL','GrowlNoise','WalkNoise','ShieldFood','LootXpCanc','KillcountInc','GiveBodies','BurningDeath','SameVersionDyeing','ColonyNoLimit','NexusGrowth','ParasiteBlock']
# message field names exactly as used in SRPSaveData.getMessageStartEnd (start,end)
MSG=[('disloCOTHIgnoreAmpStartMess','disloCOTHIgnoreAmpEndMess'),('disloCOTHTiersStartMess','disloCOTHTiersEndMess'),('disloSummonByDeathStartMess','disloSummonByDeathEndMess'),('disloPotiEffStartMess','disloPotiEffEndMess'),('disloStatsStartMess','disloStatsEndMess'),('disloDeathRaidS','disloDeathRaidE'),('disloItemDuraS','disloItemDuraE'),('disloHealingDeathS','disloHealingDeathE'),('disloDamageDeathS','disloDamageDeathE'),('disloFoodDeathS','disloFoodDeathE'),('disloDeathHighVerionsS','disloDeathHighVerionsE'),('disloParasiteNoPotionS','disloParasiteNoPotionE'),('disloHealthDrainingS','disloHealthDrainingE'),('disloFoodDrainingS','disloFoodDrainingE'),('disloNextPhaseLS','disloNextPhaseLE'),('disloGrowlNoiseS','disloGrowlNoiseE'),('disloWalkNoiseS','disloWalkNoiseE'),('disloShieldFoodS','disloShieldFoodE'),('disloLootXpCancS','disloLootXpCancE'),('disloKillcountIncS','disloKillcountIncE'),('disloGiveBodiesS','disloGiveBodiesE'),('disloBurningDeathS','disloBurningDeathE'),('disloSameVersionDyeingS','disloSameVersionDyeingE'),('disloColonyNoLimitS','disloColonyNoLimitE'),('disloNexusGrowthS','disloNexusGrowthE'),('disloParasiteBlockS','disloParasiteBlockE')]
o=[]
a=o.append
a('package com.dhanantry.scapeandrunparasites.phase;\n')
a('import com.dhanantry.scapeandrunparasites.config.SRPConfigSystems;\n')
a('/** Per-phase / per-dislodgment config lookups (SRPCommandEvolution, SRPCommandDislodgment, SRPWorldData and SRPSaveData helpers of 1.10.9). Generated by porting/tools/gen_phaseconfig.py. */')
a('public final class PhaseConfig {')
a('    private PhaseConfig() {}\n')
def sw(name,ret,typ,cases,default,arg='byte in'):
    a(f'    public static {typ} {name}({arg}) {{')
    a('        switch (in) {')
    for k,v in cases: a(f'            case {k}: return SRPConfigSystems.{v};')
    a(f'            default: return {default};')
    a('        }\n    }\n')
ph=range(1,11)
sw('neededPoints','','int',[(i,f'phaseKills{N[i]}') for i in ph],'0')
sw('delayTicks','','int',[(i,f'phaseDelayTicks{N[i]}') for i in ph],'0')
sw('vectorPointCap','','int',[(i,f'phaseVectorPointCap{N[i]}') for i in range(0,10)]+[],'Integer.MAX_VALUE','int in')
sw('warning','','String',[(i,f'phaseWarning{N[i]}') for i in range(0,11)],'""','int in')
sw('disloPhaseCooldown','','double',[(i,f'phaseDisloCooldown{N[i]}') for i in ph],'1.0')
sw('originBonusSize','','double',[(i,f'phaseOriginBonusSize{N[i]}') for i in ph],'0.0','int in')
sw('originBonusHealth','','double',[(i,f'phaseOriginBonusHealth{N[i]}') for i in ph],'0.0','int in')
sw('disloCooldown','','int',[(i,f'dislo{d}Cooldown') for i,d in enumerate(DISLO)],'0','int code')
a('    public static String disloMessage(int code, boolean start) {')
a('        switch (code) {')
for i,(s,e) in enumerate(MSG): a(f'            case {i}: return start ? SRPConfigSystems.{s} : SRPConfigSystems.{e};')
a('            default: return "missing dislo message";')
a('        }\n    }\n}')
t='\n'.join(o).replace('(byte in)','(byte in)')
t=t.replace('public static int vectorPointCap(int in) {\n        switch (in) {','public static int vectorPointCap(int in) {\n        switch (in) {\n            case -1: return SRPConfigSystems.phaseVectorPointCapZero / 2;')
# fix switch(code) naming for disloCooldown
t=t.replace('public static int disloCooldown(int code) {\n        switch (in)','public static int disloCooldown(int code) {\n        switch (code)')
d='/mnt/user-data/outputs/project/src/main/java/com/dhanantry/scapeandrunparasites/phase/'
os.makedirs(d,exist_ok=True)
open(d+'PhaseConfig.java','w').write(t+'\n')
